using System.Buffers.Binary;
using System.Text.Json;
using MphRead;
using MphRead.Mods.CustomWeapons;
using MphRead.Mods.CustomWeapons.Packages;
using MphRead.Mods.Network;

internal static class CustomReplayResourceChecks
{
    internal static int Run(string? output=null)
    {
        int checks=0;string root=Path.GetFullPath(output??Path.Combine(Path.GetTempPath(),"cw12f-resources-"+Guid.NewGuid().ToString("N")));
        void Check(bool ok,string label){if(!ok)throw new InvalidOperationException(label);checks++;}
        void Reject(Action action,string label){try{action();}catch(Exception e)when(e is InvalidDataException or IOException or ArgumentException or InvalidOperationException or OperationCanceledException){Check(true,label);return;}throw new InvalidOperationException("Expected rejection: "+label);}
        try
        {
            Directory.CreateDirectory(root);using var f=new CustomReplayStateChecks.Fixture();var descriptor=ReplayCustomWeaponDescriptor.ForInspection(f.Context);string path=Path.Combine(root,"historical");var store=new WeaponPackageStore(path);store.Install(f.Package.CopyArchive());
            var owner=new ReplayReplicaState();owner.EnableCustomInspection(descriptor);var match=new MatchStatePacket{MatchId=7,AuthorityEpoch=f.World.Start.AuthorityEpoch,RoomKey="MP3 PROVING GROUND",NextRoomKey="",Mode=(byte)GameMode.Battle,RuleBits=(uint)(MatchModifierFlags.RiftlineM7Available|MatchModifierFlags.PackagedWeaponAvailable)};byte[] packet=new byte[1+MatchStatePacket.Size];packet[0]=(byte)PacketType.MatchState;match.Write(packet.AsSpan(1));owner.Accept(packet,1);owner.Accept(ReplayCustomWeaponFact.Bootstrap(f.Context).CopyBytes(),10);owner.Accept(ReplayCustomWeaponFact.Baseline(f.Context,2,new(7,f.World.Start.AuthorityEpoch,f.Context.Bootstrap.Packages.MechanicsDigest,1001,8,0),f.Slots,Array.Empty<CustomReplicaFlight>()).CopyBytes(),11);for(int i=0;i<f.Context.Layout.Count;i++)owner.Accept(f.Pickup(owner.CustomWeapons!.Sequence+1,i).CopyBytes(),12);var checkpoint=owner.CaptureCheckpoint();
            var prepared=PreparedReplayWeaponPackage.Prepare(descriptor,store);Check(prepared.Descriptor.CopyBytes().SequenceEqual(descriptor.CopyBytes())&&prepared.Context.Digest==f.Context.Digest,"prepared resource owner uses exact historical metadata and context");
            using(var binding=prepared.Retain()){Check(binding.Package(0).PackageHash==f.Package.PackageHash&&binding.Resources(0).Model!=null,"prepared independent retain exposes exact parsed package and CPU model");for(int i=0;i<4;i++)Check(binding.Resources(0).Wave(i).SequenceEqual(WeaponPackage.DecodeWave(f.Package.CopyResource(f.Package.Project.AudioPaths[i]))),"prepared exact immutable PCM "+i);}
            Check(store.Uninstall(f.Package.PackageHash)&&store.Prune()==0,"prepared historical owner retains uninstalled immutable archive");WeaponMatchPackageBinding child;using(var gate=new FileStream(Path.Combine(path,".store.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))child=prepared.Retain();prepared.Dispose();Check(store.Prune()==0&&child.Resources(0).Model!=null,"retained independent owner survives preparation disposal without gate or marker IO");child.Dispose();Check(store.Prune()==1,"last isolated replay owner releases actual archive lease");Reject(()=>prepared.Retain().Dispose(),"disposed preparation cannot retain");Reject(()=>prepared.InspectCheckpoint(checkpoint),"disposed preparation cannot inspect checkpoint");
            string missing=Path.Combine(root,"missing");Reject(()=>PreparedReplayWeaponPackage.Prepare(descriptor,new(missing)).Dispose(),"missing exact resources refuse");Check(!Directory.Exists(missing),"failed preparation creates no store");
            store.Install(f.Package.CopyArchive());byte[] forged=descriptor.CopyBytes();int bootLength=BinaryPrimitives.ReadUInt16LittleEndian(forged.AsSpan(8)),roomLength=BinaryPrimitives.ReadUInt16LittleEndian(forged.AsSpan(10));int countAt=12+bootLength+81+roomLength;int placements=BinaryPrimitives.ReadUInt16LittleEndian(forged.AsSpan(countAt));int displayNameAt=countAt+2+placements*28+4;forged[displayNameAt]=forged[displayNameAt]==(byte)'X'?(byte)'Y':(byte)'X';Check(ReplayCustomWeaponDescriptor.TryRead(forged,out var falseName)&&falseName!.InspectContext().Digest==f.Context.Digest,"same-mechanics printable name forgery remains structurally readable");Reject(()=>PreparedReplayWeaponPackage.Prepare(falseName!,store).Dispose(),"exact historical archive display name contradicting metadata refuses");
            using(var cancel=new CancellationTokenSource()){cancel.Cancel();Reject(()=>PreparedReplayWeaponPackage.Prepare(descriptor,store,cancel.Token).Dispose(),"cancelled preparation refuses");}store.Uninstall(f.Package.PackageHash);Check(store.Prune()==1,"forged/cancelled prepare leaks no partial retained archive");
            store.Install(f.Package.CopyArchive());using(var gate=new FileStream(Path.Combine(path,".store.lock"),FileMode.Open,FileAccess.ReadWrite,FileShare.None))using(var cancel=new CancellationTokenSource()){using var entered=new ManualResetEventSlim();var task=Task.Run(()=>{entered.Set();try{PreparedReplayWeaponPackage.Prepare(descriptor,store,cancel.Token).Dispose();return false;}catch(OperationCanceledException){return true;}});Check(entered.Wait(2000)&&!task.Wait(50),"historical preparation genuinely waits behind retained OS gate");cancel.Cancel();Check(task.Wait(3000)&&task.Result,"gate-contended CPU preparation cancels without releasing external gate");}store.Uninstall(f.Package.PackageHash);Check(store.Prune()==1,"gate cancellation leaks no historical lease");
            string corruptPath=Path.Combine(root,"corrupt");var corrupt=new WeaponPackageStore(corruptPath);corrupt.Install(f.Package.CopyArchive());corrupt.Uninstall(f.Package.PackageHash);File.WriteAllBytes(Path.Combine(corruptPath,"archives",f.Package.PackageHash+".ppweapon"),new byte[]{1,2,3});Reject(()=>PreparedReplayWeaponPackage.Prepare(descriptor,corrupt).Dispose(),"corrupt exact historical archive refuses without repair");
            store.Install(f.Package.CopyArchive());using var sessionPrepared=PreparedReplayWeaponPackage.Prepare(descriptor,store);byte[] mutable=checkpoint.Bytes.ToArray();var independent=sessionPrepared.InspectCheckpoint(new(mutable));mutable.AsSpan().Clear();Check(independent.CaptureCheckpoint().Bytes.SequenceEqual(checkpoint.Bytes)&&!ReferenceEquals(independent,owner),"InspectCheckpoint returns independent immutable full CP15 owner");
            var host=new PassiveReplaySessionHost();using var session=new ReplayPlaybackSession(host);session.JoinCustomInspection(checkpoint,sessionPrepared,17);Check(session.IsActive&&session.IsCustomInspection&&session.RecordingFrame==12&&host.State.CaptureCheckpoint().Bytes.SequenceEqual(checkpoint.Bytes),"explicit passive session begins at exact captured recording frame");Reject(()=>session.AdvanceLive(12,Array.Empty<ReplayTimelineRecord>()),"native AdvanceLive cannot advance custom inspection");session.AdvanceCustomInspection(12,Array.Empty<ReplayTimelineRecord>());Check(session.IsActive&&session.RecordingFrame==12,"first explicit inspection frame may equal initial frame");var fact=ReplayCustomWeaponFact.Clock(f.Context,host.State.CustomWeapons!.Sequence+1,1004);var record=new ReplayTimelineRecord(13,1004,ReplayFactKind.CustomWeapon,fact.CopyBytes());try{session.AdvanceCustomInspection(13,new[]{record});}finally{record.Release();}Check(host.State.CustomWeapons!.World==1004&&session.RecordingFrame==13,"next contiguous accepted custom record advances exact passive state");
            // Restoring an explicit private owner replaces its complete clocks/state, never the live facade.
            var target=sessionPrepared.InspectCheckpoint(checkpoint);target.Accept(ReplayCustomWeaponFact.Clock(f.Context,target.CustomWeapons!.Sequence+1,1006).CopyBytes(),20);var targetCheckpoint=target.CaptureCheckpoint();
            var foreground=GameState.Current;var random=Rng.Current;var restoreHost=new PassiveReplaySessionHost();using(var restoreSession=new ReplayPlaybackSession(restoreHost))
            {
                restoreSession.JoinCustomInspection(checkpoint,sessionPrepared,17);restoreSession.RestoreCustomInspection(targetCheckpoint);
                Check(restoreSession.IsActive&&restoreSession.IsCustomInspection&&restoreSession.RecordingFrame==20&&restoreSession.LastFrame==20&&restoreHost.State.CustomWeapons!.World==1006&&restoreHost.State.CaptureCheckpoint().Bytes.SequenceEqual(targetCheckpoint.Bytes),"explicit restoration replaces complete CP15 state and both recording clocks exactly");
                byte[] beforeRefusal=restoreHost.State.CaptureCheckpoint().Bytes.ToArray();var nativeCheckpoint=new ReplayReplicaState().CaptureCheckpoint();
                Reject(()=>restoreSession.RestoreCustomInspection(nativeCheckpoint),"native checkpoint cannot replace active custom owner");
                Check(restoreSession.IsActive&&restoreSession.RecordingFrame==20&&restoreHost.State.CaptureCheckpoint().Bytes.SequenceEqual(beforeRefusal),"native restore refusal preserves active custom owner atomically");
                var foreignOwner=new ReplayReplicaState();foreignOwner.EnableCustomInspection(falseName!);foreignOwner.Accept(packet,1);foreignOwner.Accept(ReplayCustomWeaponFact.Bootstrap(f.Context).CopyBytes(),10);foreignOwner.Accept(ReplayCustomWeaponFact.Baseline(f.Context,2,new(7,f.World.Start.AuthorityEpoch,f.Context.Bootstrap.Packages.MechanicsDigest,1001,8,0),f.Slots,Array.Empty<CustomReplicaFlight>()).CopyBytes(),11);for(int i=0;i<f.Context.Layout.Count;i++)foreignOwner.Accept(f.Pickup(foreignOwner.CustomWeapons!.Sequence+1,i).CopyBytes(),12);
                Reject(()=>restoreSession.RestoreCustomInspection(foreignOwner.CaptureCheckpoint()),"different valid descriptor scope cannot replace prepared inspection");
                Check(restoreSession.IsActive&&restoreSession.RecordingFrame==20&&restoreHost.State.CaptureCheckpoint().Bytes.SequenceEqual(beforeRefusal)&&!NetSession.Active&&ReferenceEquals(foreground,GameState.Current)&&ReferenceEquals(random,Rng.Current),"scope refusal preserves complete owner and leaves live network globals untouched");
                restoreSession.AdvanceCustomInspection(21,Array.Empty<ReplayTimelineRecord>());Check(restoreSession.RecordingFrame==21&&restoreHost.State.CustomWeapons!.World==1006,"restored owner continues at exactly next recording frame without simulating custom state");
                Reject(()=>restoreSession.AdvanceCustomInspection(23,Array.Empty<ReplayTimelineRecord>()),"restored owner still enforces contiguous recording frames");
                Reject(()=>restoreSession.RestoreCustomInspection(targetCheckpoint),"inactive inspection cannot be resurrected by restore");
                restoreSession.JoinLive(nativeCheckpoint,0,17);byte[] nativeBefore=restoreHost.State.CaptureCheckpoint().Bytes.ToArray();
                Reject(()=>restoreSession.RestoreCustomInspection(targetCheckpoint),"native live owner cannot opt into custom restoration");
                Check(restoreSession.IsActive&&!restoreSession.IsCustomInspection&&restoreSession.RecordingFrame==0&&restoreHost.State.CaptureCheckpoint().Bytes.SequenceEqual(nativeBefore),"native owner remains unchanged after custom restore refusal");
            }
            Reject(()=>session.AdvanceCustomInspection(15,Array.Empty<ReplayTimelineRecord>()),"noncontiguous frame fails closed");Check(!session.IsActive&&!session.IsCustomInspection&&session.LastResult==ReplayOpenResult.Corrupt,"invalid explicit advance stops/reset scope and reports Corrupt");
            session.JoinCustomInspection(checkpoint,sessionPrepared,17);session.AdvanceCustomInspection(13,Array.Empty<ReplayTimelineRecord>());Check(session.IsActive&&session.RecordingFrame==13,"first explicit advance may start at initial plusone");
            var wrongFrame=new ReplayTimelineRecord(13,1004,ReplayFactKind.CustomWeapon,fact.CopyBytes());try{Reject(()=>session.AdvanceCustomInspection(14,new[]{wrongFrame}),"record clock cannot be relabelled to requested step");}finally{wrongFrame.Release();}Check(!session.IsActive&&session.LastResult==ReplayOpenResult.Corrupt,"record-frame mismatch retires session");
            session.JoinCustomInspection(checkpoint,sessionPrepared,17);var worldRecord=new ReplayTimelineRecord(12,1001,ReplayFactKind.World,new byte[]{253});try{Reject(()=>session.AdvanceCustomInspection(12,new[]{worldRecord}),"World record cannot silently restore Scene in inspection advance");}finally{worldRecord.Release();}Check(!session.IsActive&&session.LastResult==ReplayOpenResult.Corrupt,"world injection closes inspection");
            session.JoinCustomInspection(checkpoint,sessionPrepared,17);var disguisedWorld=new ReplayTimelineRecord(12,1001,ReplayFactKind.Presentation,ReplayTimelineArchive.Construction(new ReplayReplicaState().CaptureCheckpoint()));try{Reject(()=>session.AdvanceCustomInspection(12,new[]{disguisedWorld}),"construction payload cannot bypass World gate through presentation label");}finally{disguisedWorld.Release();}Check(!session.IsActive&&session.LastResult==ReplayOpenResult.Corrupt&&host.State.CustomWeapons==null,"disguised construction retires explicit inspection scope");
            session.JoinCustomInspection(checkpoint,sessionPrepared,17);session.Stop();Check(!session.IsCustomInspection&&!session.IsActive&&host.State.CustomWeapons==null,"Stop clears explicit inspection owner");Reject(()=>session.JoinLive(checkpoint,12,17),"native JoinLive cannot adopt CP15 custom scope");
            Check(store.Uninstall(f.Package.PackageHash)&&store.Prune()==0,"session proof store remains pinned only by explicit prepared resource owner");sessionPrepared.Dispose();Check(store.Prune()==1,"preparation disposal releases final pure-session resource lease");Check(!NetSession.Active,"all pure resource/session checks leave live NetSession untouched");
            File.WriteAllText(Path.Combine(root,"results.json"),JsonSerializer.Serialize(new{checks,scope="Exact historical CPU preparation/independent leases and explicit passive-session supplied records. Includes explicit pure decoder restoration; no loaded Scene, GL, playback file join, world capture/Scene restoration or authority effects claim."}));Console.WriteLine($"PASS {checks} replay package resource/passive session checks");return 0;
        }
        catch(Exception error){Console.Error.WriteLine("CUSTOM REPLAY RESOURCES FAIL "+error);return 1;}
    }
}
